window.NMX_QUIZ_BANK = {"youtube": [{"q": "Which camera on your phone usually records the best video?", "o": ["The front (selfie) camera", "The back (main) camera", "They are always identical", "Whichever has the flash"], "a": 1, "why": "The main back camera almost always has the bigger sensor and better lens. Flip the phone, frame once using the front camera, then switch."}, {"q": "What should you fix first if viewers leave in the first minute?", "o": ["Buy a 4K camera", "Your sound and your opening lines", "Add more transitions", "Upload at midnight"], "a": 1, "why": "People forgive soft video. They leave quickly when they can’t hear you clearly or the start drags."}, {"q": "Where should the window be when you film yourself indoors?", "o": ["Behind you", "In front of you or to one side", "Directly above you", "It doesn’t matter"], "a": 1, "why": "Facing a window lights your face. A window behind you turns you into a silhouette."}, {"q": "What should the first 10 seconds of a tutorial do?", "o": ["Show your channel intro and logo", "Ask people to subscribe", "State the problem or the result the viewer will get", "Explain your background in detail"], "a": 2, "why": "Viewers decide fast. Lead with why they should stay; intros and subscribe requests can wait."}, {"q": "In this recipe, what is the “promise”?", "o": ["A giveaway", "What the viewer will be able to do by the end", "Your upload schedule", "A discount code"], "a": 1, "why": "The promise tells the viewer what they’ll walk away with. The rest of the video has to deliver it."}, {"q": "What’s a better ending than “bye guys, see you next time”?", "o": ["A long recap of every point", "Pointing to one specific next video", "Ending abruptly mid-sentence", "Playing music for 30 seconds"], "a": 1, "why": "An end that hands viewers one next video keeps them watching your channel instead of leaving YouTube."}, {"q": "How many active Community Guidelines strikes lead to a channel being terminated?", "o": ["One", "Two", "Three within 90 days", "Ten in a year"], "a": 2, "why": "YouTube usually starts with a warning; strikes then expire after 90 days, and three active strikes at once terminate the channel."}, {"q": "You used a popular film song in the background. What’s most likely to happen?", "o": ["Nothing, because it’s only 20 seconds", "A Content ID claim, so the rights owner can earn from or block the video", "YouTube pays you extra for using a hit", "Your channel gets verified"], "a": 1, "why": "Short clips aren’t automatically allowed. Content ID matches the song and the owner decides what happens. Use YouTube’s Audio Library or licensed music instead."}, {"q": "When does YouTube ask you to disclose AI use?", "o": ["Whenever you used any AI tool at all", "When realistic content was generated or meaningfully altered with AI", "Only for cartoons", "Never"], "a": 1, "why": "Disclosure is for realistic content that viewers could mistake for real people, places or events. AI help with scripts or obvious animation doesn’t need it."}, {"q": "What makes light look soft and flattering on a face?", "o": ["A small, bright bulb close by", "A large light source, like a window or a bounced wall", "Light from directly above", "A coloured LED strip"], "a": 1, "why": "The bigger the light source compared with your face, the softer the shadows. Windows and white walls are big, free light sources."}, {"q": "Your voice sounds hollow and echoey. What helps most, for free?", "o": ["Recording in the bathroom", "Moving to a room with curtains, a bed or soft furniture", "Speaking louder", "Turning up the bass in editing"], "a": 1, "why": "Hard, bare surfaces bounce sound around. Soft furnishings absorb it."}, {"q": "Why record 10 seconds of silence in your room before you start?", "o": ["YouTube requires it", "It gives your editor a clean sample of the room’s background noise", "It warms up the microphone", "It improves video quality"], "a": 1, "why": "That “room tone” lets noise-reduction tools learn what to remove, and fills gaps between cuts so they don’t sound dead."}, {"q": "What’s the best format for teaching how to use a piece of software?", "o": ["A talking head with no visuals", "A screen recording with your voice, plus your face briefly", "A podcast", "A static image"], "a": 1, "why": "Learners need to see the clicks. Free tools like OBS Studio, or your phone’s built-in screen recorder, are enough."}, {"q": "What do YouTube chapters need to work?", "o": ["A paid subscription", "Timestamps in the description starting at 00:00, with at least three chapters", "At least 10,000 subscribers", "A video longer than 2 hours"], "a": 1, "why": "Add timestamps in the description starting at 00:00, with at least three chapters, each at least 10 seconds long."}, {"q": "An educational video covers five big topics. What usually works better?", "o": ["One long video covering all five quickly", "One video per idea, linked together as a series or playlist", "Removing the examples to save time", "Talking faster"], "a": 1, "why": "One idea per video is easier to finish, easier to title, and easier for search to match to the right question."}, {"q": "Which free editor is a full professional desktop editor?", "o": ["DaVinci Resolve", "Notepad", "WhatsApp", "Google Maps"], "a": 0, "why": "DaVinci Resolve’s free version handles editing, colour and audio. It needs a reasonably powerful computer."}, {"q": "What’s usually the most important edit in a beginner’s video?", "o": ["Adding transitions between every clip", "Cutting pauses, mistakes and the slow start", "Adding a 20-second intro", "Making the music louder"], "a": 1, "why": "Tight pacing keeps viewers. Effects don’t fix a slow video; cuts do."}, {"q": "Why add captions or on-screen text?", "o": ["They’re required for upload", "Many people watch without sound, and captions help non-native listeners", "They make the file smaller", "They stop copyright claims"], "a": 1, "why": "Muted viewing is common, especially on Shorts and in public places. Text keeps those viewers with you."}, {"q": "What size should a YouTube thumbnail be?", "o": ["500 × 500 pixels", "1280 × 720 pixels (16:9)", "1080 × 1920 pixels", "Any size"], "a": 1, "why": "YouTube recommends 1280 × 720, a 16:9 shape, under 2 MB, as a JPG, PNG or GIF."}, {"q": "Where should the key words in a title go?", "o": ["At the very end", "At the start, because long titles get cut off on phones", "In capital letters only", "In the description instead"], "a": 1, "why": "Mobile screens truncate long titles. Lead with what the video is about."}, {"q": "What’s the problem with a clickbait thumbnail that the video doesn’t deliver?", "o": ["Nothing, clicks are clicks", "Viewers leave early, which hurts the video, and misleading thumbnails can be removed", "It makes the file bigger", "It only matters for Shorts"], "a": 1, "why": "Early exits tell YouTube the video disappointed people, and deceptive thumbnails can break the spam rules."}, {"q": "How long can a YouTube Short be?", "o": ["15 seconds", "60 seconds", "Up to 3 minutes", "Up to 10 minutes"], "a": 2, "why": "Since October 2024, vertical or square videos up to 3 minutes can be uploaded as Shorts."}, {"q": "Does watch time from the Shorts feed count towards the long-form watch-hours requirement for the Partner Programme?", "o": ["Yes, fully", "No, it doesn’t count", "Only on weekends", "Only for music channels"], "a": 1, "why": "Shorts have their own route (Shorts views in 90 days). Long-form watch hours come from public long videos."}, {"q": "What’s a good way to turn a long video into Shorts?", "o": ["Cut random 60-second chunks", "Pick one strong moment and reframe it vertically with its own hook", "Upload the full video vertically", "Use the same thumbnail"], "a": 1, "why": "Shorts need their own hook in the first second and a vertical frame. A random chunk usually starts mid-thought."}, {"q": "From 1 February 2027, how many qualified watch hours will new channels need for ad revenue?", "o": ["4,000", "8,000", "1,000", "20,000"], "a": 1, "why": "YouTube announced in August 2026 that new applicants will need 8,000 qualified watch hours in 12 months, or 20 million qualified Shorts views in 90 days. The 1,000-subscriber requirement stays."}, {"q": "Which of these counts as a qualified watch hour?", "o": ["Watch time on an unlisted video", "Watch time on a public long video", "Views from your own ad campaign", "Watch time on a deleted video"], "a": 1, "why": "Only public long-form videos (and archived live streams) count. Private, unlisted and deleted videos, ad views and Shorts watch time don’t."}, {"q": "Do channels already in the Partner Programme have to meet the new 2027 thresholds?", "o": ["Yes, everyone reapplies", "No, the new entry bar applies to new applicants", "Only Indian channels", "Only Shorts channels"], "a": 1, "why": "Existing members aren’t affected by the new entry requirements, though everyone has to keep following the monetisation policies."}, {"q": "Which number tells you whether your title and thumbnail are working?", "o": ["Subscribers", "Impressions click-through rate", "Total views", "Number of comments"], "a": 1, "why": "Click-through rate is the share of people who saw your thumbnail and clicked. It’s mostly about packaging."}, {"q": "Your retention graph drops sharply in the first 30 seconds. What should you look at?", "o": ["The end screen", "Your opening: the hook and how fast you get to the point", "The upload time", "The video description"], "a": 1, "why": "An early drop means the start didn’t match what people expected, or took too long to get going."}, {"q": "What’s the fairest comparison for a new video’s numbers?", "o": ["A famous creator’s numbers", "Your own recent videos at the same age", "Last year’s viral video", "The YouTube average"], "a": 1, "why": "Channels differ hugely. Compare with your own videos after the same number of days."}], "branding": [{"q": "Which file format keeps a logo sharp at any size, from a favicon to a billboard?", "o": ["JPG", "PNG", "SVG (vector)", "GIF"], "a": 2, "why": "Vector formats like SVG store shapes, not pixels, so they scale without blurring. Keep PNG and JPG exports for everyday use."}, {"q": "Which colour format is meant for printing?", "o": ["HEX", "RGB", "CMYK", "sRGB"], "a": 2, "why": "CMYK describes ink. HEX and RGB describe light on screens. Good brand guidelines list both, plus a Pantone reference if you print a lot."}, {"q": "In India, how long does a trademark registration last before it needs renewing?", "o": ["1 year", "5 years", "10 years", "Forever"], "a": 2, "why": "A registered trademark in India is valid for 10 years and can be renewed every 10 years."}, {"q": "When can a brand in India use the ® symbol?", "o": ["Any time it likes", "Only after the trademark is registered", "As soon as it applies", "Only on packaging"], "a": 1, "why": "® signals a registered mark. Use ™ while the application is pending; using ® on an unregistered mark can get you into legal trouble."}, {"q": "Which of these belongs in brand guidelines?", "o": ["Last quarter’s revenue", "Logo use, colours, typefaces and tone of voice", "The founder’s CV", "The office Wi-Fi password"], "a": 1, "why": "Guidelines tell anyone making something for the brand how it should look and sound."}, {"q": "What’s a good test for a new logo?", "o": ["Does it look good at full screen only?", "Does it still work small and in one colour?", "Does it use at least five colours?", "Is it animated?"], "a": 1, "why": "Logos live on favicons, stamps and WhatsApp profile pictures. If it fails small or in one colour, simplify it."}, {"q": "How many typefaces does a small brand usually need?", "o": ["One or two", "At least five", "A new one for every post", "None"], "a": 0, "why": "One or two well-chosen typefaces, used consistently, make a brand recognisable. More usually looks messy."}, {"q": "What does “tone of voice” describe?", "o": ["How loud the brand’s ads are", "How the brand sounds in words: formal, playful, direct", "The music in the brand’s videos", "The founder’s accent"], "a": 1, "why": "Tone of voice is the personality of the brand’s writing, from website copy to push notifications."}, {"q": "What makes a positioning sentence useful?", "o": ["It sounds inspiring", "It uses the word premium", "A competitor couldn’t sign it", "It lists every product"], "a": 2, "why": "If a competitor could put their name on it, it doesn’t describe what makes you different."}, {"q": "Which part of the sentence is the proof?", "o": ["The audience", "The reason to believe the difference", "The category", "The brand name"], "a": 1, "why": "The proof is the checkable reason someone should believe your claim: a process, a person, a number."}, {"q": "When should you write the brand sentence?", "o": ["Before any design work", "After the logo is final", "Only when rebranding", "After the first ads run"], "a": 0, "why": "Every design and copy decision is easier and more consistent when the sentence already exists."}, {"q": "Why test a logo at 16 pixels?", "o": ["It improves SEO", "Browsers show tab icons about that small", "Printers need it", "It looks retro"], "a": 1, "why": "Favicons in browser tabs and bookmarks are around 16 to 32 pixels, and that’s where many people first see a logo."}, {"q": "Which file format scales without losing quality?", "o": ["JPG", "PNG", "GIF", "SVG"], "a": 3, "why": "SVG is a vector format, so it stays sharp at any size."}, {"q": "Which version should every logo have besides full colour?", "o": ["A one-colour version", "A 3D version", "An animated version", "A gradient version"], "a": 0, "why": "A one-colour version works on photos, in print and anywhere colour isn’t available."}, {"q": "What contrast ratio does WCAG AA ask for with normal body text?", "o": ["2 to 1", "3 to 1", "4.5 to 1", "10 to 1"], "a": 2, "why": "WCAG 2 level AA asks for at least 4.5 to 1 for normal-size text."}, {"q": "How many type families does a small brand usually need?", "o": ["One per channel", "Five", "A new one each campaign", "One or two"], "a": 3, "why": "A display face plus a readable text face, or one versatile family, covers almost everything."}, {"q": "Why give each colour a job?", "o": ["So people and tools use it consistently", "It’s a legal requirement", "To use more colours", "To match competitors"], "a": 0, "why": "Rules like “orange is only for buttons” are easy for designers, developers and AI tools to follow."}], "metaads": [{"q": "What size is a 4:5 image for the Facebook and Instagram feed?", "o": ["1080 × 1080", "1080 × 1350", "1920 × 1080", "1200 × 628"], "a": 1, "why": "4:5 at 1080 × 1350 takes more screen height on a phone than a square, which is why it’s the feed favourite."}, {"q": "What size suits Stories and Reels ads?", "o": ["1080 × 1920 (9:16)", "1080 × 1350 (4:5)", "1280 × 720 (16:9)", "800 × 800"], "a": 0, "why": "Full-screen vertical, 9:16, at 1080 × 1920."}, {"q": "Why keep text and logos away from the top and bottom of a 9:16 ad?", "o": ["It looks old-fashioned", "Profile names, captions and buttons cover those areas", "Meta charges more for it", "It slows the ad down"], "a": 1, "why": "Check every export against Meta’s current safe-zone overlay; the interface covers the edges."}, {"q": "Roughly how many optimisation events does an ad set need in a week to leave the learning phase?", "o": ["5", "About 50", "500", "5,000"], "a": 1, "why": "Meta’s guidance is about 50 optimisation events in a 7-day period. Budgets too small to reach that stay in learning longer."}, {"q": "In an ad named Price_Question_Static_4x5_v1, what is “Price”?", "o": ["The budget", "The angle: the reason to buy", "The bid strategy", "The audience"], "a": 1, "why": "Naming every ad Angle_Hook_Format_Size_Version lets reports show which angles win, not just which ad."}, {"q": "Which signs together suggest an ad is tiring?", "o": ["Rising frequency, falling click-through rate, rising cost per result", "More comments", "A higher budget", "A new campaign name"], "a": 0, "why": "When the same people see an ad too often, they stop clicking and each result gets more expensive."}, {"q": "How many new concepts is a sensible test set for a brand spending steadily?", "o": ["One", "Three to five, each a different angle", "Fifty", "As many as you can make"], "a": 1, "why": "A small set of genuinely different angles answers a real question. Testing everything at once teaches nothing repeatable."}, {"q": "What happens when someone taps a Click-to-WhatsApp ad?", "o": ["They see a website", "A WhatsApp chat with the business opens", "They call the business", "They download an app"], "a": 1, "why": "The ad opens a WhatsApp conversation, often with a pre-filled message, which suits Indian buyers who prefer chatting before buying."}, {"q": "Which three things decide who wins Meta’s ad auction?", "o": ["Budget, age and gender", "Bid, estimated action rate and ad quality", "Followers, likes and shares", "The time of day only"], "a": 1, "why": "Meta combines your bid, how likely the person is to act, and the ad’s quality into a total value."}, {"q": "Roughly how many optimisation events does an ad set need to leave the learning phase?", "o": ["About 50 in 7 days", "5 in a day", "500 in a month", "None"], "a": 0, "why": "Meta’s guidance is around 50 optimisation events within a 7-day period."}, {"q": "With broad targeting, what does most of the targeting work?", "o": ["Interest selections", "Your page’s follower count", "Your creative and who responds to it", "How long the ad text is"], "a": 2, "why": "People who respond to an ad teach the system who else to show it to, so different ideas reach different people."}, {"q": "Good CTR but almost no purchases usually points to…", "o": ["The CPM", "The ad’s font", "The landing page or offer", "Too many likes"], "a": 2, "why": "If people click but don’t buy, the ad did its job; the page, price or offer didn’t."}, {"q": "CPM means…", "o": ["Clicks per minute", "Cost per 1,000 impressions", "Cost per message", "Conversions per month"], "a": 1, "why": "CPM is cost per mille: what you pay for 1,000 impressions."}, {"q": "Which is a vanity metric for a sales campaign?", "o": ["Post likes", "Cost per purchase", "Conversion rate", "ROAS"], "a": 0, "why": "Likes don’t pay. For a sales campaign, judge cost per purchase and return on ad spend."}, {"q": "Why avoid editing ad sets every day?", "o": ["Meta charges for each edit", "It deletes the ad", "Significant edits can restart the learning phase", "It changes your pixel"], "a": 2, "why": "Big changes can send an ad set back into learning, making results noisy and harder to read."}, {"q": "Which is a sign your creative is getting tired?", "o": ["Frequency rising while CTR falls", "CPM falling", "More comments", "A lower budget"], "a": 0, "why": "When the same people see an ad more often and click less, it’s time for new creative."}, {"q": "How many things should one test change?", "o": ["Everything at once", "Three", "It doesn’t matter", "One"], "a": 3, "why": "Change one thing at a time so you know what caused the result."}], "geo": [{"q": "Before an AI search tool can quote your page, it must be able to…", "o": ["See your Instagram", "Find and crawl it", "Pay for it", "Play your videos"], "a": 1, "why": "If a page can’t be found and read, it can’t be used in an answer."}, {"q": "Which robots.txt user agent belongs to OpenAI’s search crawler?", "o": ["Googlebot-News", "Slurp", "OAI-SearchBot", "AdsBot"], "a": 2, "why": "OAI-SearchBot is the crawler OpenAI uses for ChatGPT search results."}, {"q": "What kind of page is easiest for an AI tool to quote?", "o": ["One that answers the question clearly near the top", "A page that is only images", "A scanned PDF", "A page behind a login"], "a": 0, "why": "Clear, early answers in plain text are easy to find, read and cite."}, {"q": "Where should the direct answer go?", "o": ["At the very end", "In an image", "In the first lines", "In the footer"], "a": 2, "why": "Put the answer in the first one or two sentences, then add detail."}, {"q": "Why use question-style headings?", "o": ["They match how people ask search and AI tools", "They make text bigger", "Google requires them", "They hide text from readers"], "a": 0, "why": "Headings phrased as real questions help skimmers and give AI tools clear question-and-answer pairs."}, {"q": "Which format is best for a comparison?", "o": ["A long paragraph", "A GIF", "A video", "A table"], "a": 3, "why": "Tables are easy for both people and machines to read and compare."}, {"q": "What is llms.txt?", "o": ["A Google ranking factor", "A proposed file that gives AI tools a map of your site", "A paid listing", "A type of virus"], "a": 1, "why": "It’s a proposed convention for a plain-text site map for AI tools. Cheap to add, but not a guaranteed ranking factor."}, {"q": "Which of these is first-hand evidence?", "o": ["A reworded encyclopedia paragraph", "A stock photo", "A list of keywords", "A test you ran with your own numbers"], "a": 3, "why": "Original tests and measurements are evidence nobody else can copy."}, {"q": "How can you check whether AI tools mention your brand?", "o": ["Ask them your customers’ questions regularly and note who they cite", "Buy more ads", "Change your logo", "Delete old posts"], "a": 0, "why": "There’s no perfect report yet, so a monthly manual check is the most reliable method."}]};
